import json
import re

data = json.load(open('/app/resources/treasury_bulletin_1953_03.json'))

# Look more comprehensively - search for all issue dates in 1952 related to treasury bills
all_bills = []
for elem in data.get('document', {}).get('elements', []):
    if 'content' in elem and elem['content']:
        content = str(elem['content'])
        # Look for treasury bills table with issue dates
        if 'Amount out-standing' in content and 'Maturity date' in content and 'Issue date' in content:
            if 'bank discount' in content.lower():
                rows = content.split('<tr>')
                for row in rows:
                    cols = re.findall(r'<td>(.*?)</td>', row)
                    if len(cols) >= 3:
                        amount = cols[0].replace('$', '').replace(',', '')
                        maturity = cols[1]
                        issue = cols[2]

                        # Check for right side of table too
                        if len(cols) >= 11:
                            amount2 = cols[7].replace('$', '').replace(',', '')
                            maturity2 = cols[8]
                            issue2 = cols[9]

                            if issue and amount:
                                all_bills.append((issue, amount, maturity))
                            if issue2 and amount2:
                                all_bills.append((issue2, amount2, maturity2))
                        elif issue and amount:
                            all_bills.append((issue, amount, maturity))

# Print all unique issue dates found
print("All treasury bill issue dates and amounts found:")
for issue, amount, maturity in sorted(all_bills):
    if issue and amount:
        print(f"Issue Date: {issue}, Amount: ${amount}M, Maturity: {maturity}")
